mapper.update:
UPDATE gateway_knowledge_job SET deleted_at = (CURRENT_TIMESTAMP AT TIME ZONE 'UTC'), version = version + 1,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime,jdbcType=TIMESTAMP}
WHERE id = #{et.id} AND tenant_id = #{et.tenantId} AND deleted_at IS NULL AND version = #{MP_OPTLOCK_VERSION_ORIGINAL}

UPDATE gateway_knowledge_job SET status = 'RUNNING', lease_owner = #{leaseOwner}, lease_token = #{leaseToken},
    lease_expires_at = #{leaseExpiresAt,jdbcType=TIMESTAMP}, revision = revision + 1, version = version + 1,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime,jdbcType=TIMESTAMP}
WHERE id = #{et.id} AND tenant_id = #{et.tenantId} AND deleted_at IS NULL AND version = #{et.version}
    AND status = #{et.status} AND lease_token = #{et.leaseToken}
    AND (next_attempt_at <= #{now,jdbcType=TIMESTAMP} OR lease_expires_at <= #{now,jdbcType=TIMESTAMP})

UPDATE gateway_knowledge_job SET lease_expires_at = #{leaseExpiresAt,jdbcType=TIMESTAMP}, version = version + 1,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime,jdbcType=TIMESTAMP}
WHERE id = #{et.id} AND tenant_id = #{et.tenantId} AND deleted_at IS NULL AND version = #{et.version}
    AND status = 'RUNNING' AND lease_token = #{leaseToken} AND lease_expires_at > #{now,jdbcType=TIMESTAMP}

UPDATE gateway_knowledge_job SET status = #{et.status}, stage = #{et.stage}, attempt = #{et.attempt},
    next_attempt_at = #{et.nextAttemptAt,jdbcType=TIMESTAMP}, error_code = #{et.errorCode},
    result = #{et.result,typeHandler=top.egon.cola.component.yuheng.admin.shared.dao.typehandler.GatewayJsonbTypeHandler},
    revision = revision + 1, version = version + 1,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime,jdbcType=TIMESTAMP}
WHERE id = #{et.id} AND tenant_id = #{et.tenantId} AND deleted_at IS NULL AND version = #{et.version}
    AND status = 'RUNNING' AND lease_token = #{leaseToken} AND lease_expires_at > #{now,jdbcType=TIMESTAMP}
